def apply(p,t):
 opts=dict(re.findall(r'^([A-D])\. (.+)$',p['prompt'],re.M));key=p['canonical_answer'][0]
 reasons=REASONS[(t,str(p['part']))];letters=[k for k in 'ABCD' if k!=key]
 assert len(opts)==4 and len(reasons)==3
 feedback='Distractor explanations: '+' '.join(f'{k}: {reason}' for k,reason in zip(letters,reasons))
 p['marking_guidance']=[f'Correct option {key} (1). '+p['canonical_answer']+' '+feedback+' No mark for more than one selected option.']
 # Deliver the explanations with feedback as well as in the marker rubric.
 p['canonical_answer']+='\n'+feedback
